ascii16_resident_call_saved_de EQU #C337   ; Saved DE input while RAM resident-call bridge stages return address
ascii16_resident_call_old_bank EQU #C339   ; Previous far lower-page bank for RAM resident-call restore
ascii16_irq_saved_bank EQU #C33A   ; Interrupted lower-page bank restored after ASCII16 RAM ISR
frame_counter       EQU #C33B   ; Frame counter (16-bit)

