call_init_components_resident:
    ; ASCII16 maps #4000-#7FFF as one page. Components live in the
    ; bank0+bank1 segment, so route through RAM when the caller may
    ; currently be executing from another lower-page overlay.
    push af
    di
    ld hl, far_call_irq_lock_depth
    inc (hl)

    ld a, 0
    ld hl, init_components
    call ASCII16_FAR_CALL_P1_RAM
    ld hl, far_call_irq_lock_depth
    dec (hl)
    ld a, (interrupt_in_progress)
    or a
    jp nz, .call_init_components_resident_done
    ld a, (far_call_irq_lock_depth)
    or a
    jp nz, .call_init_components_resident_done
    ld a, (mapper_bank_p1_current)
    or a
    jp nz, .call_init_components_resident_done
    ei
.call_init_components_resident_done:

    pop af
    ret


call_create_entity_resident:
    push af
    call mapper_push_p1
    ld a, 0
    call mapper_set_bank_p1
    pop af
    call create_entity
    push af
    call mapper_pop_p1
    pop af
    ret

call_entity_job_set_resident:
    push af
    call mapper_push_p1
    ld a, 0
    call mapper_set_bank_p1
    pop af
    call entity_job_set
    push af
    call mapper_pop_p1
    pop af
    ret

call_force_update_entity_sprite_resident:
    ; Entity init may run from an ASCII16 lower-page overlay while components.asm
    ; is split across multiple physical 16 KB segments. The per-frame sprite
    ; refresh paths call force_update_entity_sprite directly from the component
    ; segment, and GameFlow bootstraps SAT after load_world, so this external
    ; init-time wrapper must not remap P1 to a guessed component bank.
    ret


call_rebuild_used_entity_list_resident:
    ; ASCII16 maps #4000-#7FFF as one page. Components live in the
    ; bank0+bank1 segment, so route through RAM when the caller may
    ; currently be executing from another lower-page overlay.
    push af
    di
    ld hl, far_call_irq_lock_depth
    inc (hl)

    ld a, 0
    ld hl, rebuild_used_entity_list
    call ASCII16_FAR_CALL_P1_RAM
    ld hl, far_call_irq_lock_depth
    dec (hl)
    ld a, (interrupt_in_progress)
    or a
    jp nz, .call_rebuild_used_entity_list_resident_done
    ld a, (far_call_irq_lock_depth)
    or a
    jp nz, .call_rebuild_used_entity_list_resident_done
    ld a, (mapper_bank_p1_current)
    or a
    jp nz, .call_rebuild_used_entity_list_resident_done
    ei
.call_rebuild_used_entity_list_resident_done:

    pop af
    ret



call_sync_player_runtime_from_entity_resident:
