    ; bank0+bank1 segment, so route through RAM when the caller may
    ; currently be executing from another lower-page overlay.
    push af
    di
    ld hl, far_call_irq_lock_depth
    inc (hl)

    ld a, 0
    ld hl, sync_player_runtime_from_entity
    call ASCII16_FAR_CALL_P1_RAM
    ld hl, far_call_irq_lock_depth
    dec (hl)
    ld a, (interrupt_in_progress)
    or a
    jp nz, .call_sync_player_runtime_from_entity_resident_done
