; ==================================================================
; DATA BANKS — Zone-packed data (16384 bytes per zone)
; First data bank: 3
; Accessed through mapper P3 using
; (label & #3FFF) | #8000.
; BANK_NUMBER = ((label - #4000) / #4000)
; NOTE: Each zone is explicitly padded to preserve bank placement even after
;       server-side ZX0 block rewrites shrink individual data blobs.
; ==================================================================
; ------------------------------------------------------------------
; MEGAROM DATA ZONE PACKER (FIRST-FIT DECREASING)
; Zone size: 16384 bytes
; Data start address: #10000
; Total data bytes (source blocks): 2048
; Zones used: 1
; Placement policy: sort blocks by size descending, then first-fit by zone.
; ------------------------------------------------------------------
; ZONE 00 [#10000-#14000] bank 3 used=2048 slack=14336
;   + tile_pattern_bank0 (patterns) @ +#0000 size=1008
;   + tile_color_bank0 (colors) @ +#03F0 size=1008
;   + SPRITE_PLACEHOLDER_PATTERN (sprites) @ +#07E0 size=32

    org #10000
; ==================================================================
